import{_ as a,o as t,c as s,j as e,a as n,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/schueler/tutorials-fachbezogene-bermerkungen-1-aktivieren.png",l="/bilder/schueler/tutorials-fachbezogene-bermerkungen-2-memo-feld.png",u="/bilder/schueler/tutorials-fachbezogene-bermerkungen-3-memo-feld-nutzen.png",g="/bilder/schueler/tutorials-fachbezogene-bermerkungen-4-flokeln.png",c="/bilder/schueler/tutorials-fachbezogene-bermerkungen-5-gruppenprozess.png",v=JSON.parse('{"title":"Fachbezogene Bemerkungen aktivieren und erfassen","description":"","frontmatter":{"title":"Fachbezogene Bemerkungen aktivieren und erfassen","source_pageid":820,"source_revision":4392},"headers":[],"relativePath":"schild3/schueler/fachbezogene-bemerkungen-tutorial.md","filePath":"schild3/schueler/fachbezogene-bemerkungen-tutorial.md"}'),h={name:"schild3/schueler/fachbezogene-bemerkungen-tutorial.md"};function d(p,r,b,m,k,f){return t(),s("div",null,[...r[0]||(r[0]=[e("h1",{id:"fachbezogene-bemerkungen-aktivieren-und-erfassen",tabindex:"-1"},[n("Fachbezogene Bemerkungen aktivieren und erfassen "),e("a",{class:"header-anchor",href:"#fachbezogene-bemerkungen-aktivieren-und-erfassen","aria-label":'Permalink to "Fachbezogene Bemerkungen aktivieren und erfassen"'},"​")],-1),e("p",null,"Aktivieren Sie das fachbezogene Bemerkungsfeld und erfassen Sie Texte zu einzelnen Unterrichtsfächern. Die Anleitung beschreibt auch Floskeln und die gruppenweise Eintragung.",-1),e("p",null,"Fachbezogene Bemerkungen können freie Texteinträge zu beliebigen Unterrichtsfächern bei jedem einzelnen Schüler enthalten.",-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,"Diese werden etwa benutzt, um die Themenbezeichnungen für Fach- oder Abschlussarbeiten oder Titel von Projektkursarbeiten bei den Schülern speichern zu können.")],-1),i('<p>Dazu können diese Bemerkungen einzeln oder auch als Gruppenprozess bei mehreren Schülern gleichzeitig eingetragen werden.</p><h2 id="fachbezogene-bemerkungen-in-schild-aktivieren" tabindex="-1">Fachbezogene Bemerkungen in SchILD aktivieren <a class="header-anchor" href="#fachbezogene-bemerkungen-in-schild-aktivieren" aria-label="Permalink to &quot;Fachbezogene Bemerkungen in SchILD aktivieren&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-fachbezogene-bermerkungen-1-aktivieren.png"><img src="'+o+'" alt="Aktiveren von Fachbezogenen Bemerkungen über Einstellungen." loading="lazy"></a></p><p><em>Aktiveren von Fachbezogenen Bemerkungen über Einstellungen.</em></p><p>Aktivieren Sie dazu unter <strong>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen ➜ Allgemeines ➜ Ansicht</strong> die Anzeige der fachbezogenen Bemerkungen.</p><h2 id="bemerkungen-verwenden" tabindex="-1">Bemerkungen verwenden <a class="header-anchor" href="#bemerkungen-verwenden" aria-label="Permalink to &quot;Bemerkungen verwenden&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-fachbezogene-bermerkungen-2-memo-feld.png"><img src="'+l+'" alt="Das Feld für Fachbezogene Leistungen." loading="lazy"></a></p><p><em>Das Feld für Fachbezogene Leistungen.</em></p><p>Ist diese Option aktiviert steht Ihnen unter dem Karteireiter <em>Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten</em> ein Memofeld <em>Fachbez. Leistungsentw.</em> am Ende der Fächerliste zur Verfügung.</p><p><a href="/bilder/schueler/tutorials-fachbezogene-bermerkungen-3-memo-feld-nutzen.png"><img src="'+u+'" alt="Freie Eingabe oder Nutzung von vorher definierten Floskeln." loading="lazy"></a></p><p><em>Freie Eingabe oder Nutzung von vorher definierten Floskeln.</em></p><p>Ein Doppelklick auf das Memofeld öffnet den aus SchILD-NRW bekannten Texteditor und lässt nun eine freie Texteingabe zu.</p><p>Es können zu allen Fächern Bemerkungen gemacht werden.</p>',13),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der "),e("a",{href:"https://doku.svws-nrw.de/",target:"_blank",rel:"noreferrer"},"SVWS-Dokumentation"),n(" beschrieben; siehe auch "),e("a",{href:"/zeugnisse/noteneingabe.html"},"Noten mit GradeHub und WeNoM erfassen"),n(".")])],-1),i('<h2 id="floskeln-definieren" tabindex="-1">Floskeln definieren <a class="header-anchor" href="#floskeln-definieren" aria-label="Permalink to &quot;Floskeln definieren&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-fachbezogene-bermerkungen-4-flokeln.png"><img src="'+g+'" alt="Erstellen von Floskeln." loading="lazy"></a></p><p><em>Erstellen von Floskeln.</em></p><p>Unter <strong>Kataloge ➜ Floskeln bearbeiten</strong> können Sie in der <strong>Floskel-Gruppe &quot;FACH&quot;</strong> Textbausteine für diese Bemerkungen vorbereiten. Diese lassen sich anschließend per Doppelklick einfügen.</p><h2 id="fachbezogene-bemerkungen-per-gruppenprozess-eintragen" tabindex="-1">Fachbezogene Bemerkungen per Gruppenprozess eintragen <a class="header-anchor" href="#fachbezogene-bemerkungen-per-gruppenprozess-eintragen" aria-label="Permalink to &quot;Fachbezogene Bemerkungen per Gruppenprozess eintragen&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-fachbezogene-bermerkungen-5-gruppenprozess.png"><img src="'+c+'" alt="Fachbezogene Bemerkungen per Gruppenprozess eintragen." loading="lazy"></a></p><p><em>Fachbezogene Bemerkungen per Gruppenprozess eintragen.</em></p><p>Über <em>Gruppenprozesse ➜ Details zu Fächern bei Schülern ändern</em> lässt sich unter <em>Fachbezogene Bemerkung</em> eine solche bei einer im Container ausgewählten Schülermenge eintragen.</p><p>Klicken Sie hierzu auf <strong>Bearb.</strong>, so dass sich das von den Individualeintragungen bekannte Fenster öffnet. Über dieses werden eigene Eintragungen vorgenommen oder Floskeln ausgewählt.</p><p>Ein Klick auf <strong>Prozess</strong> oben links bei den Gruppenprozessen startet die Eintragung.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fachbezogene_Bemerkungen_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4392.</p>',12)])])}const _=a(h,[["render",d]]);export{v as __pageData,_ as default};
